Search Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Search Service container

Container_Boundary(search_service, "Search Service") {
    Component(Search_API_Application, "Search API Application", "Java, Spring Boot", "Provides robust backend logic, executes queries against Elasticsearch, and enforces EU data residency.")
    Component(Query_Cache_Layer, "Query Cache Layer", "Local Caffeine cache", "In-memory query cache used to check recent search results and minimize latency.")
}

Rel(Search_API_Application, Query_Cache_Layer, "Checks recent search results", "In-memory Java API")
@enduml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database container

Container_Boundary(database, "Database") {
    Component(Relational_Storage_Engine, "Relational Storage Engine", "PostgreSQL 15", "Core relational engine for ACID-compliant storage of patrons, items, and transactions within EU infrastructure.")
    Component(Connection_Pooler, "Connection Pooler", "PgBouncer", "Connection pooler to manage concurrent connections and meet performance NFRs.")
    Component(Audit_Logging_Extension, "Audit Logging Extension", "pgAudit", "Extension for strict database-level activity logging to satisfy EU compliance.")
    Component(Full_Text_Search_Index, "Full-Text Search Index", "PostgreSQL GIN Indexes", "Native full-text search index for fast metadata filtering.")
}

Rel(Connection_Pooler, Relational_Storage_Engine, "Proxied client connections [TCP, local socket]")
Rel(Relational_Storage_Engine, Audit_Logging_Extension, "Writes security and data access event logs [Internal PostgreSQL Hook]")

@enduml

Redis Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(redis_cache, "Redis Cache") {
    Component(CacheDataStore, "Cache Data Store", "Redis In-Memory Engine", "Manages internal Redis memory operations and stores cached data.")
    Component(EvictionTTLManager, "Eviction & TTL Manager", "Redis", "Manages cache eviction policies and time-to-live configurations.")
    Component(ConnectionCommandRouter, "Connection & Command Router", "Redis Cluster / Sentinel Interface", "Routes read/write and TTL configuration commands via TCP/RESP (Pooled).")
}

Rel(ConnectionCommandRouter, CacheDataStore, "Manages internal Redis memory operations", "")

@startuml
